            "SELECT id, name, email FROM customers WHERE id = :id", {"id": customer_id}
        )
    finally:
        conn.close()
    return (
        {"id": rows[0]["id"], "name": rows[0]["name"], "email": rows[0]["email"]}
        if rows
        else None
    )


def find_by_email(email):
    conn = get_conn()
    try:
        rows = conn.execute(
            "SELECT id FROM customers WHERE lower(email) = lower(:email)", {"email": email}
        )
    finally:
        conn.close()
    return rows[0]["id"] if rows else None

